import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, c in enumerate(s):
        if c in '([{':
            stack.append(c)
        else:
            if not stack or stack[-1] != match[c]:
                print(i)
                return
            stack.pop()
    print(n if stack else -1)


main()

