import sys


def reduce_pairs(s):
    while True:
        t = s.replace('()', '').replace('[]', '').replace('{}', '')
        if t == s:
            return s
        s = t


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    for k in range(1, n + 1):
        r = reduce_pairs(s[:k])
        if any(c in ')]}' for c in r):
            print(k - 1)
            return
    print(-1 if reduce_pairs(s) == '' else n)


main()

